-- 082_german_engineered_cigars.sql
-- German Engineered Cigars (GEC) — grunnlagt 2016 i Hamburg.
-- Blendes etter en «aromatisk reise» som designes først; tobakken velges etterpå.
-- Rulles i Den dominikanske republikk og Nicaragua. Kilde: cigarengineers.com
--
-- 5 blends × 16 vitolaer.
-- Idempotent: fjerner ev. eksisterende GEC-rader før innsett.

delete from cigars where brand = 'German Engineered Cigars';

insert into cigars (manufacturer, brand, series, vitola, common_format, ring_gauge, length_inches, shape, body_type, head_type, foot_type, wrapper_country, wrapper_leaf, binder, filler, country_origin, strength, price_range, description, flavor_notes) values

