('German Engineered Cigars','German Engineered Cigars','RVGN Rauchvergnügen','Panatela','Panatela',38,5.0,'Parejo',null,null,null,'Ecuador','Ecuador Hybrid Seed','Dominican Criollo 98',array['Dominican Republic','Nicaragua','United States'],'Dominican Republic',3,null,'RVGN Rauchvergnügen i slankt panatela-format. Den aromatiske reisen: full fart rundt Nürburgring i åpen racerbil en strålende morgen. Sedertre, alpeurter, mynte og fuktig skog med torv, kaffe og ingefær.',array['cedar','hay','coffee','spice','pepper','earth']),
('German Engineered Cigars','German Engineered Cigars','RVGN Rauchvergnügen','Robusto','Robusto',50,5.25,'Parejo',null,null,null,'Ecuador','Ecuador Hybrid Seed','Dominican Criollo 98',array['Dominican Republic','Nicaragua','United States'],'Dominican Republic',3,null,'RVGN Rauchvergnügen Robusto — merkets mest kjøpte format. Sjokoladeaktig dekkblad, kald trekk av høy og mynte, og en røyk av sedertre, alpeurter og fuktig skog med torv, kaffe og Szechuan-pepper.',array['cedar','hay','coffee','spice','pepper','earth']),
('German Engineered Cigars','German Engineered Cigars','RVGN Rauchvergnügen','Toro','Toro',52,6.25,'Parejo',null,null,null,'Ecuador','Ecuador Hybrid Seed','Dominican Criollo 98',array['Dominican Republic','Nicaragua','United States'],'Dominican Republic',3,null,'RVGN Rauchvergnügen Toro. Lengre brennetid gir blenden rom til å utfolde seg: sedertre, alpeurter, mynte, torv, kaffe og et snev av ingefær.',array['cedar','hay','coffee','spice','pepper','earth']),
('German Engineered Cigars','German Engineered Cigars','RVGN Rauchvergnügen','Gordo','Gordo',60,6.0,'Parejo',null,null,null,'Ecuador','Ecuador Hybrid Seed','Dominican Criollo 98',array['Dominican Republic','Nicaragua','United States'],'Dominican Republic',3,null,'RVGN Rauchvergnügen Gordo. Tykt format, kjølig trekk og fyldigere innmatsuttrykk — sedertre, urter, kaffe og pepper.',array['cedar','hay','coffee','spice','pepper','earth']),

